.bs1-marquee-wrap {
  position: relative;
  overflow: hidden;
}

/* Track holds two identical sets side-by-side → always 2× one set wide.
   Animating to -50% is therefore always exactly one set — no JS needed. */
.bs1-track {
  display: flex;
  width: max-content;
  flex-wrap: nowrap;
  align-items: center;
  padding: 0.35rem 0;
  backface-visibility: hidden;
  animation: bs1-marquee 28s linear infinite;
  will-change: transform;
}

.bs1-set {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 2.5rem;
  padding-inline: 0.5rem;
}

@media (min-width: 768px) {
  .bs1-set {
    gap: 3.75rem;
    padding-inline: 0.75rem;
  }
}

@media (min-width: 1024px) {
  .bs1-set {
    gap: 4rem;
  }
}

.bs1-slot {
  padding-inline: 1rem;
}

@media (min-width: 768px) {
  .bs1-slot {
    padding-inline: 1.5rem;
  }
}

.bs1-fade {
  pointer-events: none;
  position: absolute;
  top: 0;
  z-index: 1;
  height: 100%;
  width: 64px;
}

.bs1-fade-left {
  left: 0;
  background: linear-gradient(90deg, var(--background) 0%, transparent 100%);
}

.bs1-fade-right {
  right: 0;
  background: linear-gradient(270deg, var(--background) 0%, transparent 100%);
}

@keyframes bs1-marquee {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(-50%, 0, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .bs1-track {
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
  }

  .bs1-fade {
    display: none;
  }
}

"use client"

import { GeistSans } from "geist/font/sans"
import { Folder } from "lucide-react"
import { cn } from "@/lib/utils"

import { useTerminalAnimation } from "../hooks/use-terminal-animation"
import Spinner from "./spinner"
import PromptShell from "./prompt-shell"
import TrafficLights from "./traffic-lights"
import SyntaxCode from "./syntax-code"
import { CODE_DEMO } from "../lib/mac-os-terminal-code-segments"
import type { LineColor } from "../lib/terminal-config"

import "../styles/mac-os-terminal.css"

const codeBlockWrap = "mot-codeblock my-2 py-2 pr-2 pl-3 text-[12px] leading-[1.55]"

function colorCls(c?: LineColor) {
  if (!c) return "mot-t-line-default"
  switch (c) {
    case "green": return "mot-t-line-green"
    case "cyan":  return "mot-t-line-cyan"
    case "dim":   return "mot-t-line-dim"
  }
}

export default function MacOsTerminal({ className }: { className?: string }) {
  const { lines, typed, phase, codeIdx, scrollRef } = useTerminalAnimation()

  return (
    <div
      className={cn(
        "relative mot-terminal mot-terminal-shell mx-auto w-full min-w-0 max-w-2xl overflow-hidden rounded-md",
        className,
      )}
    >
      <div className="mot-terminal-titlebar relative flex h-8 shrink-0 select-none items-center">
        <TrafficLights />
        <div
          className={cn(
            GeistSans.className,
            "mot-terminal-title flex w-full items-center justify-center gap-1.5 px-20 text-center text-[12px] font-medium tracking-tight",
          )}
        >
          <Folder size={14} className="size-3.5 shrink-0" fill="#3b8eea" stroke="none" strokeWidth={0} aria-hidden />
          <span>Projects</span>
          <span className="text-[#a1a1aa] dark:text-[#6b6b6b]" aria-hidden>—</span>
          <span>-zsh</span>
          <span className="text-[#a1a1aa] dark:text-[#6b6b6b]" aria-hidden>—</span>
          <span className="tabular-nums">80×24</span>
        </div>
      </div>

      <div
        ref={scrollRef}
        className="mot-terminal-body max-h-192 min-h-120 overflow-y-auto px-4 py-2.5 text-left font-mono text-[13px] leading-relaxed"
        style={{ scrollbarWidth: "none" }}
      >
        {lines.map((line) => (
          <div key={line.id} className={cn("mot-terminal-line-in", colorCls(line.color))}>
            {line.spinning ? (
              <span><Spinner /> {line.text}</span>
            ) : (
              line.text || "\u00A0"
            )}
          </div>
        ))}

        {(phase === "typingCode" || phase === "done") && (
          <div className={codeBlockWrap}>
            <pre className="m-0 whitespace-pre-wrap wrap-break-word font-mono">
              <SyntaxCode visibleChars={phase === "done" ? CODE_DEMO.length : codeIdx} />
              {phase === "typingCode" && <span className="mot-terminal-cursor" />}
            </pre>
          </div>
        )}

        {(phase === "idle" || phase === "typing") && (
          <div className="flex min-w-0 flex-wrap items-center gap-x-1 gap-y-0">
            <PromptShell />
            <span className="min-w-0">{typed}</span>
            <span className="mot-terminal-cursor" />
          </div>
        )}

        {phase === "done" && (
          <div className="mt-2 flex items-center gap-x-1">
            <PromptShell />
            <span className="mot-terminal-cursor" />
          </div>
        )}
      </div>
    </div>
  )
}

import type { Brand } from "../lib/brands"

