"use client"

import { useEffect, useState } from "react"

const FRAMES = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]

export default function Spinner() {
  const [frame, setFrame] = useState(0)
  useEffect(() => {
    const t = setInterval(() => setFrame((f) => (f + 1) % FRAMES.length), 80)
    return () => clearInterval(t)
  }, [])
  return <span>{FRAMES[frame]}</span>
}

import type { ReactNode } from "react"
import { CODE_SYNTAX_PARTS } from "../lib/mac-os-terminal-code-segments"

export default function SyntaxCode({ visibleChars }: { visibleChars: number }) {
  let remaining = visibleChars
  const nodes: ReactNode[] = []
  let key = 0
  for (const { t, c } of CODE_SYNTAX_PARTS) {
    if (remaining <= 0) break
    const take = Math.min(t.length, remaining)
    if (take > 0) {
      nodes.push(
        <span key={key++} className={c}>
          {t.slice(0, take)}
        </span>,
      )
      remaining -= take
    }
  }
  return <>{nodes}</>
}

export default function TrafficLights() {
  return (
    <div className="absolute left-3 flex gap-2" aria-hidden>
      <button type="button" tabIndex={-1} className="size-3 shrink-0 rounded-full bg-[#ff5f57] ring-1 ring-black/10" />
      <button type="button" tabIndex={-1} className="size-3 shrink-0 rounded-full bg-[#febc2e] ring-1 ring-black/10" />
      <button type="button" tabIndex={-1} className="size-3 shrink-0 rounded-full bg-[#28c840] ring-1 ring-black/10" />
    </div>
  )
}

// Phase flow: idle → typing → output → typingCode → done → idle (loops)
import { useEffect, useRef, useState } from "react"

import {
  COMMAND, INIT_LINES, OUTPUT_SEQUENCE, PROMPT,
  TYPE_CODE_MS, TYPE_CODE_NEWLINE_MS, TYPE_SPEED,
  type Line, type Phase,
} from "../lib/terminal-config"
import { CODE_DEMO } from "../lib/mac-os-terminal-code-segments"

export function useTerminalAnimation() {
  const [lines, setLines] = useState<Line[]>(INIT_LINES)
  const [typed, setTyped] = useState("")
  const [phase, setPhase] = useState<Phase>("idle")
  const [outIdx, setOutIdx] = useState(0)
  const [codeIdx, setCodeIdx] = useState(0)
  const idRef = useRef(10)
  const spinTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const scrollRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [lines, typed, codeIdx, phase])

  useEffect(() => {
    if (phase !== "idle") return
    const t = setTimeout(() => setPhase("typing"), 1600)
    return () => clearTimeout(t)
  }, [phase])

  useEffect(() => {
    if (phase !== "typing") return
    if (typed.length < COMMAND.length) {
      const t = setTimeout(() => setTyped(COMMAND.slice(0, typed.length + 1)), TYPE_SPEED)
      return () => clearTimeout(t)
    }
    const t = setTimeout(() => {
      setLines((prev) => [...prev, { id: idRef.current++, text: `${PROMPT}${COMMAND}` }])
      setTyped("")
      setOutIdx(0)
      setPhase("output")
    }, 360)
    return () => clearTimeout(t)
  }, [phase, typed])

  useEffect(() => {
    if (phase !== "output") return
    if (outIdx >= OUTPUT_SEQUENCE.length) {
      const t = setTimeout(() => { setCodeIdx(0); setPhase("typingCode") }, 450)
      return () => clearTimeout(t)
    }
    const item = OUTPUT_SEQUENCE[outIdx]
    if (item.type === "spinner") {
      const t = setTimeout(() => {
        const spinId = idRef.current++
        setLines((prev) => [...prev, { id: spinId, text: item.text, spinning: true }])
        spinTimerRef.current = setTimeout(() => {
          setLines((prev) =>
            prev.map((l) =>
              l.id === spinId
                ? { ...l, spinning: false, text: `✓ ${item.doneText}`, color: "green" as const }
                : l,
            ),
          )
          setOutIdx((i) => i + 1)
        }, item.duration)
      }, item.delay)
      return () => {
        clearTimeout(t)
        if (spinTimerRef.current) clearTimeout(spinTimerRef.current)
      }
    }
    const t = setTimeout(() => {
      setLines((prev) => [...prev, { id: idRef.current++, text: item.text, color: item.color }])
      setOutIdx((i) => i + 1)
    }, item.delay)
    return () => clearTimeout(t)
  }, [phase, outIdx])

  useEffect(() => {
    if (phase !== "typingCode") return
    if (codeIdx >= CODE_DEMO.length) {
      const t = setTimeout(() => setPhase("done"), 320)
      return () => clearTimeout(t)
    }
    const ch = CODE_DEMO[codeIdx]
    const delay = ch === "\n" ? TYPE_CODE_NEWLINE_MS : TYPE_CODE_MS
    const t = setTimeout(() => setCodeIdx((i) => i + 1), delay)
    return () => clearTimeout(t)
  }, [phase, codeIdx])

  useEffect(() => {
    if (phase !== "done") return
    const t = setTimeout(() => {
      idRef.current = 10
      setTyped("")
      setOutIdx(0)
      setCodeIdx(0)
      setLines(INIT_LINES)
      setPhase("idle")
    }, 8000)
    return () => clearTimeout(t)
  }, [phase])

  return { lines, typed, phase, codeIdx, scrollRef }
}

export type LineColor = "green" | "cyan" | "dim"

export type Phase = "idle" | "typing" | "output" | "typingCode" | "done"

export interface Line {
  id: number
  text: string
  color?: LineColor
  spinning?: boolean
}

export type OutputItem =
  | { type: "line"; text: string; color?: LineColor; delay: number }
  | { type: "spinner"; text: string; doneText: string; delay: number; duration: number }

export const PROMPT = "user@macbook app % "
export const COMMAND = "pnpm i ai"
export const TYPE_SPEED = 38
export const TYPE_CODE_MS = 11
export const TYPE_CODE_NEWLINE_MS = 48

export const INIT_LINES: Line[] = []

export const OUTPUT_SEQUENCE: OutputItem[] = [
  {
    type: "spinner",
    text: "Resolving dependencies…",
    doneText: "Resolved dependencies",
    delay: 240,
    duration: 900,
  },
  {
    type: "spinner",
    text: "Downloading + installing ai…",
    doneText: "Downloaded and installed ai",
    delay: 140,
    duration: 1400,
  },
]

/* mac-os-terminal — scoped so consumers need not import app globals */


.mot-terminal {
  --mot-t-shell-bg: #fafafa;
  --mot-t-body-bg: #ffffff;
  --mot-t-body-fg: #3f3f46;
  --mot-t-border: rgb(0 0 0 / 0.1);
  --mot-t-ring: rgb(0 0 0 / 0.06);
  --mot-t-shadow: 0 20px 40px -12px rgb(0 0 0 / 0.12);
  --mot-t-titlebar-bg: #ececec;
  --mot-t-titlebar-border: rgb(0 0 0 / 0.08);
  --mot-t-title-fg: #3c3c3c;
  --mot-t-line-green: #15803d;
  --mot-t-line-cyan: #0f766e;
  --mot-t-line-dim: #71717a;
  --mot-terminal-cursor-bg: #27272a;
}

.dark .mot-terminal {
  --mot-t-shell-bg: #1e1e1e;
  --mot-t-body-bg: #1e1e1e;
  --mot-t-body-fg: #cccccc;
  --mot-t-border: rgb(255 255 255 / 0.1);
  --mot-t-ring: rgb(0 0 0 / 0.2);
  --mot-t-shadow: 0 20px 40px -12px rgb(0 0 0 / 0.45);
  --mot-t-titlebar-bg: #2d2d2d;
  --mot-t-titlebar-border: rgb(255 255 255 / 0.08);
  --mot-t-title-fg: #d4d4d8;
  --mot-t-line-green: #16c60c;
  --mot-t-line-cyan: #61d6d6;
  --mot-t-line-dim: #767676;
  --mot-terminal-cursor-bg: #cccccc;
}

.mot-terminal-shell {
  border: 1px solid var(--mot-t-border);
  background-color: var(--mot-t-shell-bg);
  box-shadow: var(--mot-t-shadow);
  outline: 1px solid var(--mot-t-ring);
  outline-offset: -1px;
}

.mot-terminal-titlebar {
  border-bottom: 1px solid var(--mot-t-titlebar-border);
  background-color: var(--mot-t-titlebar-bg);
}

.mot-terminal-title {
  color: var(--mot-t-title-fg);
}

.mot-terminal-body {
  background-color: var(--mot-t-body-bg);
  color: var(--mot-t-body-fg);
}

.mot-t-line-default {
  color: var(--mot-t-body-fg);
}

.mot-t-line-green {
  color: var(--mot-t-line-green);
}

.mot-t-line-cyan {
  color: var(--mot-t-line-cyan);
}

.mot-t-line-dim {
  color: var(--mot-t-line-dim);
}

.mot-terminal-cursor {
  display: inline-block;
  width: 8px;
  height: 1em;
  margin-left: 1px;
  vertical-align: text-bottom;
  background-color: var(--mot-terminal-cursor-bg);
  animation: mot-terminal-blink 1.15s step-start infinite;
}

@keyframes mot-terminal-blink {
  0%,
  49.9% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

.mot-terminal-line-in {
  animation: mot-terminal-line-fade 0.12s ease-out both;
}

@keyframes mot-terminal-line-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.mot-terminal-body::-webkit-scrollbar {
  display: none;
}

/* Syntax highlight panel — token colors swap via CSS vars on .dark */

.mot-codeblock {
  --mot-sh-kw: #b83280;
  --mot-sh-str: #166534;
  --mot-sh-fn: #6d28d9;
  --mot-sh-num: #0369a1;
  --mot-sh-prop: #18181b;
  --mot-sh-var: #0e7490;
  --mot-sh-punct: #a21caf;
  --mot-cursor-fg: #27272a;

  border-left-width: 2px;
  border-left-style: solid;
  border-left-color: rgb(59 142 234 / 0.55);
  background-color: rgb(244 244 245 / 0.95);
}

.dark .mot-codeblock {
  --mot-sh-kw: #ff79c6;
  --mot-sh-str: #50fa7b;
  --mot-sh-fn: #bd93f9;
  --mot-sh-num: #8be9fd;
  --mot-sh-prop: #f8f8f2;
  --mot-sh-var: #8be9fd;
  --mot-sh-punct: #ff79c6;
  --mot-cursor-fg: #cccccc;

  border-left-color: rgb(59 142 234 / 0.45);
  background-color: rgb(0 0 0 / 0.55);
}

.mot-sh-kw {
  color: var(--mot-sh-kw);
}
.mot-sh-str {
  color: var(--mot-sh-str);
}
.mot-sh-fn {
  color: var(--mot-sh-fn);
}
.mot-sh-num {
  color: var(--mot-sh-num);
}
.mot-sh-prop {
  color: var(--mot-sh-prop);
}
.mot-sh-var {
  color: var(--mot-sh-var);
}
.mot-sh-punct {
  color: var(--mot-sh-punct);
}

.mot-codeblock .mot-terminal-cursor {
  background-color: var(--mot-cursor-fg);
}
